"""Complete mayonnaise sauces and full fish and tomato salads."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']

r=add(11,'Czech Majonéza with Olive Oil',18,20,'A two-yolk mayonnaise is slowly whisked with olive oil and finished with vinegar.',[yolks(2),salt(.25),pepper(.125),oil(240),vinegar(30)],['Set a clean small bowl on a damp towel. Whisk {{yolks}}, {{salt}} and {{pepper}} until smooth.','Measure {{oil}} into a jug. Whisk it into the yolks drop by drop at first, then in a very thin stream once the mixture thickens. Keep whisking until all the oil is incorporated.','Gradually whisk in {{vinegar}}, a teaspoon at a time, until smooth. If the sauce separates, start with 1 teaspoon cold drinking water in a clean bowl and gradually whisk the separated sauce into it; this is an optional modern repair addition.',COLD],'The original koflík is interpreted as a modern 240 ml cup, not a recovered universal historical volume. The source vinegar-last method is retained without repeating the claim that earlier vinegar necessarily causes curdling. Salt and pepper amounts are supplied. Melted butter is preserved as a complete alternative.');eggsource(r)
vi=[I('butter',225,'g','unsalted butter','Use the olive-oil base recipe for a dairy-free version.') if i['key']=='oil' else copy.deepcopy(i) for i in r['ingredients']];vs=copy.deepcopy(r['steps']);vs[1]='Melt {{butter}} over low heat, then cool until just lukewarm and still liquid, about 35–40°C (95–104°F). Whisk it into the seasoned yolks drop by drop at first, then in a thin stream until all is incorporated.';vs[-1]=COLD+' The butter version firms when cold. Let only the portion being served soften for about 10–15 minutes before using.';variant(r,'melted-butter','Czech mayonnaise with melted butter',vi,vs);r['notes']+=' The butter alternative uses an explicit modern 225 g working amount rather than treating the oil volume as a butter weight.'

r=add(15,'Chilean Lemon and Spice Mayonnaise',18,20,'Lemon juice and aromatic vinegar brighten a mayonnaise lightly seasoned with white pepper and nutmeg.',[yolks(2),lemon(30),salt(.25),I('pepper',.125,'tsp','ground white pepper','Use the same amount of black pepper.'),I('nutmeg',.0625,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.'),oil(240),vinegar(10,'tarragon')],emulsion(['yolks','lemon','salt','pepper','nutmeg','vinegar']),'The source allows one or two yolks; two are chosen for the base, with a full one-yolk variation. Unspecified oil, vinegar and seasonings receive modern quantities. The unnamed spices are explicitly interpreted as white pepper and nutmeg. Prepared mustard remains optional in a complete named variation.');eggsource(r)
variant(r,'one-yolk','Chilean mayonnaise with one yolk',[dict(i,amount=1) if i['key']=='yolks' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
variant(r,'mustard','Chilean mayonnaise with mustard',copy.deepcopy(r['ingredients'])+[I('mustard',1,'tsp','prepared Dijon mustard','Use the same amount of prepared yellow mustard.')],emulsion(['yolks','lemon','salt','pepper','nutmeg','vinegar','mustard']))

r=add(16,'Chilean Cooked-Yolk Bayonesa',6,35,'Mashed hard-boiled yolk gives this small oil-and-vinegar sauce a lightly textured consistency.',[eggs(1),water(750),vinegar(15),salt(.125),pepper(.0625),oil(60)],boil()+['Keep the cooked yolk for the sauce and refrigerate the white for another dish. Push the yolk through a fine sieve into a small bowl. Whisk in {{vinegar}}, {{salt}} and {{pepper}}.','Gradually whisk in {{oil}}, adding it drop by drop at first and then in a thin stream. Mash any small yolk particles against the bowl until evenly blended. This cooked-yolk sauce may remain slightly textured; stir before serving.',COLD],'The original calls for a hard-boiled yolk, not raw egg. All missing oil, vinegar and seasoning amounts are supplied as modern choices. Olive, anchovy and smoked-herring additions remain separate complete variations rather than being included together.')
for key,label,item in [('olives','Bayonesa with olives',I('olives',20,'g','pitted green olives, finely chopped','Use the same weight of pitted black olives.')),('anchovies','Bayonesa with anchovies',I('anchovies',10,'g','ready-to-eat anchovy fillets packed in oil, drained and finely chopped','Use the olive variation for a fish-free option.')),('herring','Bayonesa with smoked herring',I('herring',20,'g','fully cooked ready-to-eat smoked herring fillet, bones removed and finely chopped','Use the anchovy variation for a different flavor.'))]:
 st=copy.deepcopy(r['steps']);st.insert(-1,'Stir in '+tk(key)+' and distribute evenly.');variant(r,key,label,copy.deepcopy(r['ingredients'])+[item],st)

r=add(18,'El Practicón Small-Batch Mayonnaise',6,20,'A yolk-rich Spanish mayonnaise uses a modest amount of oil and a final touch of lemon.',[yolks(2),salt(.125),I('pepper',.0625,'tsp','ground white pepper','Use the same amount of black pepper.'),vinegar(.25),oil(45),lemon(5)],['Set a clean small bowl on a damp towel. Whisk {{yolks}}, {{salt}}, {{pepper}} and {{vinegar}} until smooth. Keep the bowl away from heat.','Measure {{oil}} into a jug and add it drop by drop while whisking continuously for about 10–15 minutes, until evenly bound and creamy. This yolk-rich formula is softer than a high-oil mayonnaise.','Whisk in {{lemon}} slowly and serve in small portions.',COLD],'The original Spanish confirms one and a half tablespoons oil per yolk: three tablespoons total, not deciliters. The few drops of initial vinegar become a disclosed modern 0.25 ml approximation, since drop sizes vary. Missing lemon and seasoning quantities are supplied. A clean steady bowl replaces the elaborate bottle-stopper device.');eggsource(r)
variant(r,'vinegar-finish','Spanish mayonnaise with vinegar finish',[dict(i,name='white wine vinegar for finishing',substitution='Use the lemon base recipe if preferred.') if i['key']=='lemon' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))

r=add(19,'Guatemalan Four-Yolk Mayonnaise',20,50,'Four yolks make a rich mayonnaise finished with vinegar after a short refrigerated rest.',[yolks(4),oil(240),salt(.25),vinegar(15)],['Set a clean bowl on a damp towel and whisk {{yolks}} until smooth. Measure {{oil}} into a jug.','Whisk in the oil drop by drop at first, then in a thin stream once the mixture begins to thicken. Continue until all the measured oil is incorporated.','Cover and refrigerate at 4°C (40°F) or colder for 30 minutes, preserving the source resting stage with explicit refrigeration.','Whisk in {{salt}} and {{vinegar}} gradually until smooth.',COLD],'The source specifies four yolks and a tablespoon of finishing vinegar but gives no final oil quantity. The 240 ml oil and quarter-teaspoon salt are modern choices. The source half-hour rest is refrigerated. Its optional tablespoon of French mustard is retained as a complete variation.');eggsource(r)
st=copy.deepcopy(r['steps']);st.insert(-1,'Whisk in {{mustard}} until evenly blended.');variant(r,'french-mustard','Guatemalan mayonnaise with French mustard',copy.deepcopy(r['ingredients'])+[I('mustard',1,'tbsp','prepared Dijon mustard','Use the same amount of prepared yellow mustard.')],st)

r=add(23,'Bauvilliers and Périgord Mayonnaise',15,40,'A cooked yolk joins two pasteurized yolks in a rich olive-oil mayonnaise with vinegar and pepper.',[eggs(1),water(750),yolks(2),vinegar(15),salt(.25),pepper(.125),oil(180)],boil()+['Reserve the cooked white in the refrigerator for another dish. Push the cooked yolk through a fine sieve into a bowl and whisk with {{yolks}}, {{vinegar}}, {{salt}} and {{pepper}} until smooth.','Measure {{oil}} into a jug. Whisk in drop by drop at first, then in a thin stream once the sauce thickens. Continue until all the measured oil is incorporated and the sauce is evenly creamy.',COLD],'The original two raw yolks and one cooked yolk are retained, with commercially pasteurized yolks used for the uncooked part. The missing oil and seasoning amounts are supplied modern choices. The original twenty-minute stirring instruction is replaced by gradual incorporation to the actual smooth endpoint.');eggsource(r)

r=add(8,'Canadian Fish and Lettuce Mayonnaise Salad',4,75,'Cold poached fish and shredded pale lettuce are coated in a sharp cooked-yolk dressing and garnished with egg-white rings.',[I('fish',550,'g','boneless skinless cod fillet','Use the same weight of haddock or pollock fillet.'),water(1000,'fishwater'),eggs(3),water(1000),oil(30),vinegar(90),I('sugar',2,'tsp','granulated sugar','Use the same amount of caster sugar.'),salt(1),mustard(.5),pepper(1),I('lettuce',200,'g','pale inner butterhead lettuce leaves','Use the same weight of pale romaine hearts.')],boil()+['Bring {{fishwater}} to a bare simmer in a wide pan. Check {{fish}} for bones and remove them, then add to the water. Poach gently for 6–10 minutes until the thickest part reaches 63°C (145°F) and flakes easily. Lift out and drain. Spread in a shallow dish, cover and refrigerate promptly until cold, about 30–45 minutes.','Separate the cooked egg yolks and whites. Mash the yolks with {{oil}}, then mix in {{sugar}}, {{salt}}, {{mustard}} and {{pepper}}. Whisk in {{vinegar}} a little at a time until smooth. Keep covered in the refrigerator while preparing the salad.','Wash {{lettuce}}, dry well and shred. Cut the cold fish into pieces about 2.5 cm long and gently mix with the lettuce in a salad bowl. Slice the egg whites into rings or curved strips.','Just before serving, spoon the dressing over the fish and lettuce and garnish with the egg whites. Serve immediately so the lettuce remains crisp. Refrigerate leftovers within 2 hours at 4°C (40°F) or colder and use within 1 day.'],'The pound of cooked fish becomes an explicit estimated 550 g raw fillet yielding about 450 g after poaching; actual cooked yield varies. Blanched lettuce is interpreted as pale inner leaves, not lettuce boiled in water. The source unusually sharp 3:1 vinegar-to-oil ratio and full teaspoon pepper are retained. Full fish and egg cooking methods, lettuce weight and chilling are supplied.');r['category']='Salads';r['source']+=' Fish endpoint: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures .'

r=add(12,'Czech Tomato Salad with Egg and Mustard Dressing',8,75,'Sliced ripe tomatoes are chilled under a tangy mustard dressing made with cooked yolks, pasteurized yolk and a little butter.',[I('tomatoes',1800,'g','firm ripe tomatoes, about twelve medium','Use the same weight of mixed ripe tomatoes.'),eggs(4),water(1500),yolks(1),salt(1),I('paprika',.5,'tsp','sweet paprika','Use the same amount of smoked paprika for a different flavor.'),I('sugar',1,'tbsp','granulated sugar','Use the same volume of caster sugar.'),I('butter',15,'g','unsalted butter, softened','Use the same weight of a block-style dairy-free butter alternative.'),I('mustard',2,'tbsp','prepared Dijon mustard','Use the same volume of prepared yellow mustard.'),vinegar(120)],boil()+['Reserve the cooked egg whites in the refrigerator for another dish. Push the cooked yolks through a fine sieve into a bowl. Whisk in {{yolks}}, {{salt}}, {{paprika}}, {{sugar}}, {{butter}} and {{mustard}} until smooth.','Gradually whisk in {{vinegar}} until the dressing is evenly blended. This is a tangy pourable dressing rather than a thick high-oil mayonnaise.','Wash {{tomatoes}}, dry them and remove the cores. Slice into rounds and arrange on a shallow serving platter. Spoon the dressing over the tomatoes.','Cover and refrigerate for about 45 minutes at 4°C (40°F) or colder before serving. Serve chilled. Keep leftovers refrigerated and use within 1 day.'],'The source twelve tomatoes become an explicit modern 1.8 kg. Its small cup of vinegar is interpreted as 120 ml, not a verified historical cup conversion. Four cooked yolks and one uncooked yolk are retained, with the latter commercially pasteurized. Prepared mustard is the explicit modern interpretation. Complete egg preparation and prompt refrigeration are supplied.');r['category']='Salads';eggsource(r)

assert len(newids)==8,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full sauces, named variations and fish/tomato salads completed with measured preparation and source-specific choices','repair-batch-022.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

